INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_46_m_46_2_93',
  'A data lake requires batch ingestion of CSV files from Amazon S3 into a structured format in the AWS Glue Data Catalog. Order the steps to achieve this using an AWS Glue crawler.',
