INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_46_m_46_1_134',
  'An organization needs to ensure that sensitive training data and model artifacts are never exposed to the public internet during SageMaker operations, adhering to strict security protocols. Match the security measure to its primary benefit.',
  'matching',
  '{"A":"VPC-only mode","B":"KMS encryption","C":"Least privilege IAM"}'::json,
  NULL,
  'VPC-only mode (Option A) for SageMaker training and inference ensures that all network traffic remains within a private Amazon VPC, providing private network access and preventing exposure to the public internet. KMS encryption (Option B) directly contributes to data confidentiality by encrypting data at rest and in transit. Implementing Least privilege IAM (Option C) by granting only necessary permissions is crucial for minimizing unauthorized actions and reducing the attack surface.',
  NOW(),
  'quiz_domain46_10',
  NOW(),
  20,
  '{"left":["VPC-only mode","KMS encryption","Least privilege IAM"],"right":["Private network access","Data confidentiality","Minimizing unauthorized actions"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_46_1',
  'hard'
) ON CONFLICT (id) DO NOTHING;

