INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_46_m_46_3_113',
  'Match each model optimization technique available in Amazon SageMaker to its primary goal.',
  'matching',
  '{"A":"SageMaker Neo compilation","B":"Quantization","C":"Pruning"}'::json,
  NULL,
  'SageMaker Neo compilation (left: 0) optimizes machine learning models to run faster on specific target hardware, such as edge devices or AWS Inferentia. Quantization (left: 1) reduces the precision of model weights and activations, leading to smaller model sizes and faster inference with minimal accuracy loss. Pruning (left: 2) removes redundant or less important connections and parameters from a neural network, reducing model complexity and size.',
  NOW(),
  'quiz_domain46_10',
  NOW(),
  53,
  '{"left":["SageMaker Neo compilation","Quantization","Pruning"],"right":["Optimizes models for specific hardware","Reduces model precision for smaller size","Removes redundant model parameters"]}'::json,
