) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_46_m_46_3_117',
  'Match each security practice for machine learning model artifacts to its primary purpose.',
  'matching',
  '{"A":"Encryption at rest","B":"Encryption in transit","C":"IAM policies"}'::json,
  NULL,
  'Encryption at rest (left: 0) protects model artifacts stored in services like Amazon S3 or Amazon EBS by encrypting the data before it''s written to disk. Encryption in transit (left: 1) secures data as it moves across networks, such as between a client and a SageMaker endpoint, using protocols like TLS. IAM policies (left: 2) define who can access, create, update, or delete model artifacts and other related resources, enforcing granular access control.',
  NOW(),
  'quiz_domain46_10',
  NOW(),
  57,
  '{"left":["Encryption at rest","Encryption in transit","IAM policies"],"right":["Protects stored model artifacts","Secures data during network transfer","Controls access to model resources"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_46_3',
  'medium'
) ON CONFLICT (id) DO NOTHING;

