INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_46_m_46_3_121',
  'Match the Amazon SageMaker model optimization technique to its primary method of transforming a model for efficient deployment, especially on resource-constrained environments.',
  'matching',
  '{"A":"SageMaker Neo compilation","B":"Model quantization","C":"Model pruning"}'::json,
  NULL,
  'SageMaker Neo compilation (Option A) performs hardware-specific optimization, compiling models to run efficiently on various target devices and hardware architectures. Model quantization (Option B) transforms a model by reducing precision for size, typically converting floating-point numbers to lower-bit integers, which reduces memory footprint and speeds up inference. Model pruning (Option C) optimizes a model by removing redundant connections or weights, leading to a sparsified model with fewer parameters and faster inference.',
  NOW(),
  'quiz_domain46_10',
  NOW(),
  61,
  '{"left":["SageMaker Neo compilation","Model quantization","Model pruning"],"right":["Hardware-specific optimization","Reducing precision for size","Removing redundant connections"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_46_3',
  'hard'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
