  '{"left":["SageMaker Neo","Quantization","Pruning"],"right":["Cross-platform deployment","Reduced model size","Sparsified model"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_46_3',
  'hard'
) ON CONFLICT (id) DO NOTHING;

