INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_47_m_47_3_60',
  'A data scientist is analyzing a dataset to identify potential linear relationships between two continuous variables and to detect outliers. Which visualization techniques are most suitable for this initial exploratory analysis? (Select TWO.)',
  'multiple',
  '["Histogram","Time Series Plot","Scatter Plot","Confusion Matrix","Box Plot"]'::json,
  '{2,4}',
  'Option C (Scatter Plot) is ideal for visualizing the relationship between two continuous variables, making it easy to spot linear or non-linear patterns and potential outliers in their joint distribution. Option E (Box Plot) is excellent for identifying outliers within a single continuous variable, which is a crucial step in initial exploratory analysis. Option A (Histogram) shows the distribution of a single variable, not relationships between two. Option B (Time Series Plot) is for data over time. Option D (Confusion Matrix) is an evaluation metric for classification models, not an exploratory data analysis tool.',
  NOW(),
  'quiz_domain47_10',
  NOW(),
  9,
  NULL,
  NULL,
  'm_47_3',
