) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_48_m_48_2_64',
  'Which two model types are best suited for processing sequential data, such as time series or natural language? (Select TWO.)',
  'multiple',
  '["Support Vector Machines (SVMs)","Recurrent Neural Networks (RNNs)","Decision Trees","Transformers","K-Nearest Neighbors (KNN)"]'::json,
  '{1,3}',
  'Recurrent Neural Networks (RNNs) (Option B) are designed to handle sequential data by maintaining an internal state that captures information from previous steps in the sequence. Transformers (Option D) have revolutionized natural language processing and are highly effective for sequential data due to their attention mechanisms. Support Vector Machines (SVMs) (Option A), Decision Trees (Option C), and K-Nearest Neighbors (KNN) (Option E) are general-purpose models not specifically optimized for sequential data''s inherent temporal dependencies.',
  NOW(),
  'quiz_domain48_10',
  NOW(),
  75,
  NULL,
  NULL,
  'm_48_2',
