INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_47_m_47_3_80',
  'When performing cluster analysis on a dataset, a data scientist often uses an elbow plot to determine the optimal number of clusters. Order the steps involved.',
  'ordering',
  '["Plot the WCSS (Within-Cluster Sum of Squares) against the number of clusters.","Run the clustering algorithm for a range of k values.","Identify the ''elbow point'' on the plot.","Calculate the WCSS for each k value."]'::json,
  '{1,3,0,2}',
  'To create an elbow plot, the clustering algorithm (e.g., K-Means) must first be run for a predefined range of ''k'' (number of clusters) values (Option B). For each ''k'' value, the Within-Cluster Sum of Squares (WCSS) is calculated, which measures the compactness of clusters (Option D). These WCSS values are then plotted against their corresponding ''k'' values (Option A). Finally, the ''elbow point'' on this plot, where the rate of decrease in WCSS significantly slows down, is identified as the optimal number of clusters (Option C).',
  NOW(),
  'quiz_domain47_10',
  NOW(),
  5,
  NULL,
  NULL,
  'm_47_3',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
