INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_49_m_49_2_56',
  'Which AWS services are suitable for performing large-scale data transformations and feature engineering for ML models? (Select TWO.)',
  'multiple',
  '["Amazon SQS","AWS Glue","Amazon Redshift","Amazon Kinesis Data Firehose","Amazon EMR"]'::json,
  '{1,4}',
  'Option B (AWS Glue) is a serverless data integration service that makes it easy to discover, prepare, and combine data for analytics, machine learning, and application development. It''s excellent for large-scale ETL (Extract, Transform, Load) operations. Option E (Amazon EMR) is a managed cluster platform that simplifies running big data frameworks like Apache Spark and Hadoop to process and analyze vast amounts of data, making it suitable for complex feature engineering. Option A (Amazon SQS) is a message queuing service. Option C (Amazon Redshift) is a data warehouse. Option D (Amazon Kinesis Data Firehose) is for loading streaming data into data stores.',
  NOW(),
  'quiz_domain49_10',
  NOW(),
  69,
