INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_48_m_48_5_96',
  'Match each machine learning evaluation metric to its primary purpose.',
  'matching',
  '{"A":"AUC-ROC","B":"Precision","C":"Recall","D":"F1 Score"}'::json,
  NULL,
  'AUC-ROC (left: 0, right: 0) is a robust metric for binary classification, representing the model''s ability to distinguish between classes. Precision (left: 1, right: 1) quantifies the accuracy of positive predictions. Recall (left: 2, right: 2) measures the model''s ability to find all positive instances. F1 Score (left: 3, right: 3) provides a single metric that balances precision and recall, especially useful for imbalanced datasets.',
  NOW(),
  'quiz_domain48_10',
  NOW(),
  1,
  '{"left":["AUC-ROC","Precision","Recall","F1 Score"],"right":["Measures the area under the Receiver Operating Characteristic curve, indicating classifier performance.","Measures the proportion of true positive predictions among all positive predictions.","Measures the proportion of true positive predictions among all actual positives.","The harmonic mean of precision and recall, balancing both metrics."]}'::json,
  '{"left":[0,1,2,3],"right":[0,1,2,3]}'::jsonb,
  'm_48_5',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_48_m_48_5_97',
  'Match the type of model evaluation to its description.',
  'matching',
  '{"A":"Offline Evaluation","B":"Online Evaluation","C":"Holdout Validation"}'::json,
  NULL,
  'Offline Evaluation (left: 0, right: 0) uses historical data to test a model''s performance without impacting live users. Online Evaluation (left: 1, right: 1) involves deploying the model and observing its performance with real-time user interactions, commonly through A/B testing. Holdout Validation (left: 2, right: 2) is a fundamental technique where a portion of the dataset is reserved for testing the model after it has been trained on the remaining data.',
  NOW(),
  'quiz_domain48_10',
  NOW(),
  2,
  '{"left":["Offline Evaluation","Online Evaluation","Holdout Validation"],"right":["Assessing model performance using historical data before deployment.","Assessing model performance in a live production environment, often with A/B testing.","Splitting data into training and test sets, using the test set for final model assessment."]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_48_5',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_48_m_48_5_98',
  'Match the model evaluation concept to its definition.',
  'matching',
  '{"A":"Confusion Matrix","B":"Bias","C":"Variance"}'::json,
  NULL,
  'A Confusion Matrix (left: 0, right: 0) is a specific table layout that allows visualization of the performance of an algorithm, typically a supervised learning one (in unsupervised learning it is usually called a matching matrix). Bias (left: 1, right: 1) refers to the error from erroneous assumptions in the learning algorithm, causing the model to miss relevant relations between features and target outputs. Variance (left: 2, right: 2) refers to the error from sensitivity to small fluctuations in the training set, causing the model to learn noise from the training data.',
  NOW(),
  'quiz_domain48_10',
  NOW(),
  3,
  '{"left":["Confusion Matrix","Bias","Variance"],"right":["A table summarizing the performance of a classification algorithm.","The error introduced by approximating a real-world problem, leading to underfitting.","The sensitivity of the model to small fluctuations in the training data, leading to overfitting."]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_48_5',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
