INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_48_m_48_1_95',
  'Match the ML problem characteristic to its definition.',
  'matching',
  '{"A":"Solvable ML Problem","B":"Measurable ML Problem","C":"Business KPI Mapping"}'::json,
  NULL,
  'A Solvable ML Problem (left: 0, right: 0) implies that the necessary data and algorithmic approaches are available and feasible. A Measurable ML Problem (left: 1, right: 1) means that the impact and performance of the ML solution can be tracked and evaluated using quantifiable metrics. Business KPI Mapping (left: 2, right: 2) is the process of translating high-level business goals into specific, actionable ML objectives and metrics.',
  NOW(),
  'quiz_domain48_10',
  NOW(),
  20,
  '{"left":["Solvable ML Problem","Measurable ML Problem","Business KPI Mapping"],"right":["A problem where sufficient data and appropriate ML techniques exist for a solution.","A problem where the success of the ML solution can be quantified with metrics.","Connecting business performance indicators to specific machine learning objectives."]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_48_1',
