INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_49_m_49_3_91',
  'Match each AWS service to its primary security function within an ML solution.',
  'matching',
  '{"A":"AWS IAM","B":"AWS KMS","C":"Amazon S3 Bucket Policy"}'::json,
  NULL,
  'AWS IAM (left item 0) is fundamental for managing access to AWS resources, defining who can do what. AWS KMS (left item 1) is specifically designed for creating and controlling encryption keys, crucial for data protection. An Amazon S3 Bucket Policy (left item 2) is used to grant or deny access to Amazon S3 buckets and their objects, ensuring secure data storage.',
