) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_49_m_49_3_92',
  'Match the AWS security concept to its description for protecting ML data.',
  'matching',
  '{"A":"Encryption at Rest","B":"Encryption in Transit","C":"Least Privilege"}'::json,
  NULL,
  'Encryption at Rest (left item 0) refers to protecting data when it is stored on physical storage, such as in Amazon S3 or Amazon EBS. Encryption in Transit (left item 1) ensures data is secured as it travels between systems over a network, often using TLS/SSL. The principle of Least Privilege (left item 2) dictates that users and services should only be granted the minimum permissions required to perform their tasks, reducing potential security risks.',
  NOW(),
  'quiz_domain49_10',
  NOW(),
  2,
  '{"left":["Encryption at Rest","Encryption in Transit","Least Privilege"],"right":["Protects data stored on disk","Secures data moving across networks","Grants only necessary permissions"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_49_3',
  'easy'
) ON CONFLICT (id) DO NOTHING;

