INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_49_m_49_2_94',
  'Match each AWS AI service to its primary domain.',
  'matching',
  '{"A":"Amazon Rekognition","B":"Amazon Comprehend","C":"Amazon Polly"}'::json,
  NULL,
  'Amazon Rekognition (left item 0) is an AI service that makes it easy to add image and video analysis to your applications. Amazon Comprehend (left item 1) is a natural language processing (NLP) service that uses machine learning to find insights and relationships in text. Amazon Polly (left item 2) is a service that turns text into lifelike speech, allowing you to create applications that talk.',
  NOW(),
  'quiz_domain49_10',
  NOW(),
  44,
  '{"left":["Amazon Rekognition","Amazon Comprehend","Amazon Polly"],"right":["Image and video analysis","Natural Language Processing (NLP)","Text-to-speech synthesis"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_49_2',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_49_m_49_2_95',
  'Match the AWS ML service to its core capability.',
  'matching',
  '{"A":"Amazon SageMaker","B":"Amazon Lex","C":"Amazon Transcribe"}'::json,
  NULL,
  'Amazon SageMaker (left item 0) is a fully managed service that provides every developer and data scientist with the ability to build, train, and deploy machine learning models quickly. Amazon Lex (left item 1) is a service for building conversational interfaces into any application using voice and text. Amazon Transcribe (left item 2) is an automatic speech recognition (ASR) service that makes it easy for developers to add speech-to-text capability to their applications.',
  NOW(),
  'quiz_domain49_10',
  NOW(),
  45,
  '{"left":["Amazon SageMaker","Amazon Lex","Amazon Transcribe"],"right":["Build, train, and deploy ML models","Build conversational interfaces","Converts speech to text"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_49_2',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_49_m_49_2_96',
  'Match the Amazon SageMaker feature to its primary use case.',
  'matching',
  '{"A":"SageMaker Built-in Algorithms","B":"SageMaker Notebook Instances","C":"SageMaker Training Jobs"}'::json,
  NULL,
  'SageMaker Built-in Algorithms (left item 0) provide pre-packaged, optimized machine learning algorithms that can be used directly for training. SageMaker Notebook Instances (left item 1) offer a fully managed Jupyter notebook environment for interactive data exploration, model development, and experimentation. SageMaker Training Jobs (left item 2) are used to run machine learning training scripts on managed infrastructure, handling resource provisioning and scaling.',
  NOW(),
  'quiz_domain49_10',
  NOW(),
  46,
  '{"left":["SageMaker Built-in Algorithms","SageMaker Notebook Instances","SageMaker Training Jobs"],"right":["Pre-packaged ML algorithms","Interactive development environment","Runs model training scripts"]}'::json,
  '{"left":[0,1,2],"right":[0,1,2]}'::jsonb,
  'm_49_2',
  'easy'
) ON CONFLICT (id) DO NOTHING;

INSERT INTO public.question (id, text, type, options, correct_answer, explanation, created_at, quiz_id, modified_at, index, pairs, matches, module_id, difficulty)
VALUES (
  'q_49_m_49_2_97',
  'Match the AWS service to its application in data processing for ML.',
  'matching',
  '{"A":"AWS Glue","B":"Amazon Kinesis","C":"Amazon Athena"}'::json,
  NULL,
  'AWS Glue (left item 0) is a serverless data integration service that makes it easy to discover, prepare, and combine data for analytics, machine learning, and application development. Amazon Kinesis (left item 1) is a platform for streaming data on AWS, enabling real-time processing of large streams of data. Amazon Athena (left item 2) is an interactive query service that makes it easy to analyze data directly in Amazon S3 using standard SQL.',
