  (NOW(), 'quiz_domain49_10', 'q_49_m_49_2_100'),
  (NOW(), 'quiz_domain49_10', 'q_49_m_49_2_101'),
  (NOW(), 'quiz_domain49_10', 'q_49_m_49_2_102'),
  (NOW(), 'quiz_domain49_10', 'q_49_m_49_2_103'),
  (NOW(), 'quiz_domain49_10', 'q_49_m_49_2_104'),
  (NOW(), 'quiz_domain49_10', 'q_49_m_49_2_105'),
  (NOW(), 'quiz_domain49_10', 'q_49_m_49_2_106'),
  (NOW(), 'quiz_domain49_10', 'q_49_m_49_2_107')
ON CONFLICT DO NOTHING;

-- Update quiz question count
UPDATE public.quiz q
SET questions = sub.cnt,
    modified_at = NOW()
FROM (
  SELECT quiz_id, COUNT(*)::int AS cnt
  FROM public.quiz_question
  WHERE quiz_id = 'quiz_domain49_10'
  GROUP BY quiz_id
) sub
WHERE q.id = sub.quiz_id;

COMMIT;
